def solve(input_str):
    p = int(input_str.strip())
    return (
        "# Tuning shuffle partitions balances parallelism vs. task overhead:\n"
        "# too few partitions = large, slow shuffle tasks; too many = excessive scheduling overhead\n"
        "spark = SparkSession.builder \\\n"
        f'.config("spark.sql.shuffle.partitions", {p}) \\\n'
        ".getOrCreate()"
    )

print(solve("200"))
